&lt;/div&gt;
&lt;p style=&quot;line-height: 1.3; text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3; text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot;&gt;75-100K annual base compensation&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
